def _png_chunk(chunk_type: bytes,  bytes) -> bytes:
    crc = binascii.crc32(chunk_type)
    crc = binascii.crc32(data, crc) & 0xffffffff
    return struct.pack(">I", len(data)) + chunk_type + data + struct.pack(">I", crc)

def _make_icon_png(size: int) -> bytes:
    w = h = int(size)
    raw = bytearray()
    cx = (w - 1) / 2.0
    cy = (h - 1) / 2.0
    r0 = min(w, h) * 0.42
    r1 = min(w, h) * 0.46
    for y in range(h):
        raw.append(0)
        fy = (y - cy) / (h - 1)
        for x in range(w):
            fx = (x - cx) / (w - 1)
            d = (fx * fx + fy * fy) ** 0.5
            t = min(1.0, max(0.0, (d - r0) / max(1e-6, (r1 - r0))))
            a = int(255 * (1.0 - t))
            u = x / (w - 1)
            c1 = (124, 92, 255)
            c2 = (255, 86, 189)
            c3 = (36, 216, 255)
            if u < 0.5:
                uu = u * 2.0
                r = int(c1[0] * (1 - uu) + c2[0] * uu)
                g = int(c1[1] * (1 - uu) + c2[1] * uu)
                b = int(c1[2] * (1 - uu) + c2[2] * uu)
            else:
                uu = (u - 0.5) * 2.0
                r = int(c2[0] * (1 - uu) + c3[0] * uu)
                g = int(c2[1] * (1 - uu) + c3[1] * uu)
                b = int(c2[2] * (1 - uu) + c3[2] * uu)
            ring = 1.0 - min(1.0, max(0.0, (d - (r0 * 0.92)) / (r0 * 0.25)))
            ring = ring * ring
            r = min(255, int(r + 18 * ring))
            g = min(255, int(g + 18 * ring))
            b = min(255, int(b + 18 * ring))
            raw.extend((r, g, b, a))
    ihdr = struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0)
    compressed = zlib.compress(bytes(raw), level=9)
    return b"\x89PNG\r\n\x1a\n" + _png_chunk(b"IHDR", ihdr) + _png_chunk(b"IDAT", compressed) + _png_chunk(b"IEND", b"")

def _json_error(status_code: int, message: str) -> Response:
    payload = {"error": {"message": message}}
    resp = Response(json.dumps(payload), status=status_code, mimetype="application/json")
    resp.headers["Cache-Control"] = "no-store"
    return resp

@app.after_request
