        max_tokens = int(max_tokens)
    except Exception:
        return _json_error(400, "max_tokens must be an integer")
    if max_tokens < 1:
        return _json_error(400, "max_tokens must be >= 1")
    temperature = data.get("temperature", 1.0)
    try:
        temperature = float(temperature)
    except Exception:
        return _json_error(400, "temperature must be a number")
    top_k = data.get("top_k", 1.0)
    try:
        top_k = int(float(top_k))
    except Exception:
        return _json_error(400, "top_k must be a number")
    if top_k < 1:
        return _json_error(400, "top_k must be >= 1")

    vllm_base = _resolve_vllm_base_url()
    provider_url = f"{vllm_base}/v1/chat/completions"

    payload: Dict[str, Any] = {
        "model": data.get("model") or "glm-4.7",
        "messages": messages,
        "temperature": temperature,
        "top_k": top_k,
        "stream": True,
        "max_tokens": max_tokens
    }

    headers: Dict[str, str] = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "Cache-Control": "no-store"
    }

    if VLLM_PROVIDER_API_KEY:
        headers["Authorization"] = f"Bearer {VLLM_PROVIDER_API_KEY}"

    target_url = provider_url
    if use_memory:
        if not SUPERMEMORY_API_KEY:
            return _json_error(500, "SUPERMEMORY_API_KEY is not set")
        if "Authorization" not in headers:
            return _json_error(500, "VLLM_PROVIDER_API_KEY is not set")
        target_url = f""
        headers["x-supermemory-api-key"] = SUPERMEMORY_API_KEY
        headers["x-sm-user-id"] = str(user_id)
        headers["x-sm-conversation-id"] = str(conversation_id)

    def generate() -> Generator[str, None, None]:
        try:
            with requests.post(target_url, headers=headers, json=payload, stream=True, timeout=(15, None)) as r:
                r.raise_for_status()
                for raw_line in r.iter_lines(decode_unicode=True):
                    if raw_line is None:
                        continue
                    line = raw_line.strip()
                    if not line:
                        continue
                    if line.startswith(""):
                        yield line + "\n\n"
                    else:
                        yield " " + line + "\n\n"
        except requests.HTTPError as e:
            status = getattr(e.response, "status_code", 502)
            try:
                body = e.response.text if e.response is not None else ""
            except Exception:
                body = ""
            err_payload = {"error": {"message": "upstream error", "status": status, "body": body[:2000]}}
            yield " " + json.dumps(err_payload, ensure_ascii=False) + "\n\n"
        except Exception as e:
            err_payload = {"error": {"message": "server error", "detail": str(e)}}
            yield " " + json.dumps(err_payload, ensure_ascii=False) + "\n\n"

    resp = Response(generate(), mimetype="text/event-stream")
    resp.headers["Cache-Control"] = "no-store"
    resp.headers["X-Accel-Buffering"] = "no"
    return resp

@app.post("/api/memory/add")
def api_memory_add() -> Response:
    if not SUPERMEMORY_API_KEY:
        return _json_error(500, "SUPERMEMORY_API_KEY is not set")
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return _json_error(400, "invalid JSON body")
    content = data.get("content")
    if not isinstance(content, str) or not content.strip():
        return _json_error(400, "content must be a non-empty string")
    user_id = data.get("user_id") or "me"
    conversation_id = data.get("conversation_id") or "default"
    metadata = data.get("metadata")
    if metadata is None:
        metadata = {}
    if not isinstance(metadata, dict):
        return _json_error(400, "metadata must be an object")
    safe_meta: Dict[str, Any] = {"source": "chat", "conversation_id": str(conversation_id)}
    for k, v in metadata.items():
        if isinstance(k, str) and isinstance(v, (str, int, float, bool)) and len(k) <= 64:
            safe_meta[k] = v
    doc_payload = {"content": content, "containerTag": str(user_id), "metadata": safe_meta}
    try:
        r = requests.post(
            "",
            headers={"Authorization": f"Bearer {SUPERMEMORY_API_KEY}", "Content-Type": "application/json"},
            json=doc_payload,
            timeout=30
        )
        resp = Response(r.content, status=r.status_code, mimetype=r.headers.get("Content-Type", "application/json"))
        resp.headers["Cache-Control"] = "no-store"
        return resp
    except Exception as e:
        return _json_error(502, str(e))

@app.get("/api/health")
def api_health() -> Response:
    try:
        vllm_base = _resolve_vllm_base_url()
        url = f"{vllm_base}/v1/models"
        headers: Dict[str, str] = {}
        if VLLM_PROVIDER_API_KEY:
            headers["Authorization"] = f"Bearer {VLLM_PROVIDER_API_KEY}"
        r = requests.get(url, headers=headers, timeout=10)
        ok = 200 <= r.status_code < 300
        return Response(json.dumps({"status": "ok" if ok else "degraded", "vllm_status": r.status_code}), mimetype="application/json", status=200 if ok else 503)
    except Exception as e:
        return Response(json.dumps({"status": "error", "detail": str(e)}), mimetype="application/json", status=503)

@app.get("/<path:path>")
def static_fallback(path: str) -> Response:
    if path == "index.html":
        return send_from_directory(BASE_DIR, "index.html")
    if os.path.exists(os.path.join(BASE_DIR, path)) and os.path.isfile(os.path.join(BASE_DIR, path)):
        return send_from_directory(BASE_DIR, path)
    abort(404)

